{
  "name": "RPLIDAR 二维激光雷达",
  "name_en": "RPLIDAR 2D LiDAR",
  "manufacturer": "Slamtec",
  "description": "用于获取周围环境二维距离与角度扫描数据的旋转式激光雷达。该设备可连续输出测距点，形成一圈扫描缓冲区，常用于机器人避障、环境感知、建图与定位实验。",
  "description_en": "A rotating 2D LiDAR used to acquire distance-and-angle scan data of the surrounding environment. It continuously outputs range measurements and maintains a recent full-scan buffer, making it suitable for robotics experiments involving obstacle avoidance, perception, mapping, and localization.",
  "actions": [
    {
      "action_name": "auto-poll",
      "description": "读取一个激光测量点，并更新当前扫描缓冲区。",
      "description_en": "Read one LiDAR measurement and update the current scan buffer."
    },
    {
      "action_name": "auto-update",
      "description": "持续更新激光雷达测量数据。",
      "description_en": "Continuously update LiDAR measurement data."
    },
    {
      "action_name": "auto-run_threaded",
      "description": "返回线程模式下最近缓存的一圈测量结果。",
      "description_en": "Return the most recent cached scan measurements for threaded operation."
    },
    {
      "action_name": "auto-run",
      "description": "在设定轮询时间内采集并返回一批激光测量数据。",
      "description_en": "Collect and return a batch of LiDAR measurements over the configured polling interval."
    },
    {
      "action_name": "auto-shutdown",
      "description": "停止激光雷达采集并关闭设备连接。",
      "description_en": "Stop LiDAR acquisition and shut down the device connection."
    }
  ],
  "tag_hints": [
    "2D LiDAR",
    "laser range scanning",
    "robot perception",
    "obstacle detection",
    "SLAM",
    "distance-angle measurements",
    "mobile robotics"
  ]
}

